export function getA1VocabularyByDomain(domainId) {
  return A1_CORE_VOCABULARY.filter(w => w.course_domain === domainId);
}

export function getA1VocabularyByUnit(unitId) {
  return A1_CORE_VOCABULARY.filter(w => w.course_unit_id === unitId);
}
